        "code": "def content_filter_brute(feed: str, K: int, pattern: str) -> list:\n    n = len(feed)\n    m = len(pattern)\n\n    # --- Part 1: Longest window with at most K distinct (brute force) ---\n    max_len = 0\n    for i in range(n):\n        seen_chars = set()\n        for j in range(i, n):\n            seen_chars.add(feed[j])\n            if len(seen_chars) > K:\n                break  # More than K distinct, stop extending\n            max_len = max(max_len, j - i + 1)\n\n    # --- Part 2: Anagram indices (brute force) ---\n    sorted_pattern = sorted(pattern)\n    anagram_indices = []\n    for i in range(n - m + 1):\n        if sorted(feed[i:i + m]) == sorted_pattern:\n            anagram_indices.append(i)\n\n    return [max_len, anagram_indices]",
